// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 <= type(uint256).max - amount2);
        uint256 totalSent = amount1 + amount2;

        vm.deal(sender, totalSent);
        vm.startPrank(sender);
        c.addToBalance{value: amount1}();
        c.addToBalance{value: amount2}();
        vm.stopPrank();

        assertEq(c.getBalance(sender), totalSent);
    }
}
